// Traduce lo que manda la app a UNA fila del Excel.
// Las horas llegan en ISO UTC desde el teléfono y se guardan en hora de Lima.
// La fila se identifica por 'id': el Sheet usa append-or-update por esa columna,
// así los reintentos de la app no duplican y el 'fin' completa la fila del 'inicio'.
const TZ = 'America/Lima';
const b = ($input.first().json.body) || {};

function fecha(iso) { return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso)); }
function hora(iso)  { return new Intl.DateTimeFormat('es-PE', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(iso)); }
function esIso(v)   { return typeof v === 'string' && !isNaN(new Date(v).getTime()); }
function invalido(msg) { return [{ json: { valido: false, error: msg } }]; }

if (!b.id || typeof b.id !== 'string') return invalido('Falta id');
const evento = b.evento;
const accion = b.accion;

if (evento === 'panal') {
  if (!esIso(b.fecha_hora)) return invalido('fecha_hora inválida');
  if (!['Pipí', 'Popó', 'Ambos'].includes(b.contenido)) return invalido('contenido inválido: ' + b.contenido);
  return [{ json: { valido: true, _hoja: 'Pañales', id: b.id, fecha: fecha(b.fecha_hora), hora: hora(b.fecha_hora), contenido: b.contenido } }];
}

if (evento !== 'lactancia' && evento !== 'sueno') return invalido('evento desconocido: ' + evento);
if (!['inicio', 'fin', 'cancelar'].includes(accion)) return invalido('accion desconocida: ' + accion);
if (!esIso(b.inicio)) return invalido('inicio inválido');

const fila = {
  valido: true,
  _hoja: evento === 'lactancia' ? 'Lactancia' : 'Sueño',
  id: b.id,
  fecha: fecha(b.inicio),
  hora_inicio: hora(b.inicio)
};

if (accion === 'inicio') fila.estado = 'En curso';
if (accion === 'cancelar') fila.estado = 'Descartada';
if (accion === 'fin') {
  if (!esIso(b.fin)) return invalido('fin inválido');
  fila.hora_fin = hora(b.fin);
  fila.duracion_min = Math.max(0, Math.round((new Date(b.fin) - new Date(b.inicio)) / 60000));
  fila.estado = 'Terminada';
  if (evento === 'lactancia') {
    if (!['Pecho', 'Leche materna (biberón)', 'Fórmula'].includes(b.tipo)) return invalido('tipo inválido: ' + b.tipo);
    fila.tipo = b.tipo;
    if (b.tipo === 'Pecho') {
      fila.onzas = '';
    } else {
      const oz = Number(b.onzas);
      if (!(oz > 0 && oz <= 15)) return invalido('onzas inválidas: ' + b.onzas);
      fila.onzas = oz;
    }
  }
}

return [{ json: fila }];
